<?php
 namespace Pterodactyl\Services\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Permission; use Illuminate\Support\Str; use Illuminate\Support\Facades\Hash; class Demo { public const KEY = 'demo'; public const REFUSAL = 'This is the demo account. It can open everything and change nothing, make an account of your own to do this for real.'; public const NO_IP = '0.0.0.0'; public const PERMISSIONS = [ Permission::ACTION_WEBSOCKET_CONNECT, Permission::ACTION_ACTIVITY_READ, Permission::ACTION_STARTUP_READ, Permission::ACTION_FILE_READ, Permission::ACTION_FILE_READ_CONTENT, Permission::ACTION_BACKUP_READ, Permission::ACTION_DATABASE_READ, Permission::ACTION_SCHEDULE_READ, Permission::ACTION_ALLOCATION_READ, Permission::ACTION_USER_READ, Permission::ACTION_SETTINGS_RENAME, Permission::ACTION_SETTINGS_REINSTALL, ]; private static ?User $resolved = null; private static bool $looked = false; public static function user(): ?User { if (self::$looked) { return self::$resolved; } self::$looked = true; return self::$resolved = User::query()->where('demo', true)->first(); } public static function exists(): bool { return self::user() !== null; } public static function is(mixed $user): bool { return $user instanceof User && $user->demo === true; } public static function credentials(): ?array { $user = self::user(); if ($user === null) { return null; } $stored = Settings::get(self::KEY) ?? []; if ((int) ($stored['user'] ?? 0) !== $user->id) { return null; } $password = (string) ($stored['password'] ?? ''); if ($password === '') { return null; } return [ 'username' => $user->username, 'email' => $user->email, 'password' => $password, ]; } public static function promote(User $user, string $password = ''): string { $stored = Settings::get(self::KEY) ?? []; $kept = (int) ($stored['user'] ?? 0) === $user->id ? (string) ($stored['password'] ?? '') : ''; $plain = $password !== '' ? $password : ($kept !== '' ? $kept : Str::random(14)); User::query()->where('demo', true)->whereKeyNot($user->id)->update(['demo' => false]); $user->forceFill([ 'demo' => true, 'root_admin' => false, 'use_totp' => false, 'totp_secret' => null, 'totp_authenticated_at' => null, 'password' => Hash::make($plain), ])->saveOrFail(); Settings::put(self::KEY, ['user' => $user->id, 'password' => $plain]); self::forget(); return $plain; } public static function demote(User $user): void { if ($user->demo) { $user->forceFill(['demo' => false])->saveOrFail(); } $stored = Settings::get(self::KEY) ?? []; if ((int) ($stored['user'] ?? 0) === $user->id) { Settings::forget(self::KEY); } self::forget(); } public static function payload(): array { $credentials = self::credentials(); return [ 'enabled' => $credentials !== null, 'username' => $credentials['username'] ?? '', 'password' => $credentials['password'] ?? '', ]; } public static function forget(): void { self::$resolved = null; self::$looked = false; } } 